/* Standalone N26 matches. Only skirmish records are written by these controls. */
(function(){'use strict';
const E=v=>esc(String(v??'')),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,literal=v=>`<span data-user-text>${E(v)}</span>`,account=()=>window.AccountParity?.account?.id||'',copy=v=>JSON.parse(JSON.stringify(v));
const keys={deploymentId:'deployment',objectiveId:'objective',crewId:'crew_selection'},labels={deploymentId:['Deployment','배치'],objectiveId:['Objective / mission','목표·미션'],crewId:['Crew selection','크루 선택']};
const RULE={sequence:'n26-core-prebattle-sequence',budget:'n26-core-gang-budget',injury:'n26-core-lasting-injuries',field:'official-003-core-underhive-battlefield-setup',crew:'official-003-core-crew-selection-methods',reinforce:'official-003-core-reinforcements',deploy:'official-003-core-deployment-order',tactics:'n26-core-tactics-selection',round:'n26-core-round-sequence'};
let draftCrew=null;const noteDrafts=new Map(),noteKey=(s,i)=>JSON.stringify([account(),s.id,i]);
const rows=key=>(RULES_DATA.scenarioEntries||[]).filter(r=>r.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26'&&r.table_type===keys[key]&&!r.gang_type_id).sort((a,b)=>a.d6_min-b.d6_min);
const row=(s,key)=>rows(key).find(r=>r.id===s[key]);
const name=r=>r?L(r.name,r.name_ko||r.name):L('Not selected','선택하지 않음');
const description=r=>r?L(r.description_en||r.description,r.description):'';
const button=(action,en,ko,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-sk-action="${action}" ${extra}>${L(en,ko)}</button>`;
const help=(rule,en='Rule',ko='룰 보기')=>button('help',en,ko,`data-sk-rule="${E(RULE[rule]||rule)}"`,'small');
const list=()=>Array.isArray(data.skirmishes)?data.skirmishes:[];
function usable(s){return s&&s.edition==='N26'&&['setup','battle','completed'].includes(s.stage)&&Number.isSafeInteger(s.round)&&s.round>=1&&Array.isArray(s.participants)&&s.participants.length===2&&s.participants.every(p=>p&&typeof p.name==='string'&&typeof p.gangId==='string'&&Array.isArray(p.crew)&&Number.isSafeInteger(p.vp)&&p.vp>=0);}
const selected=()=>list().find(s=>s.id===data.selectedSkirmish&&usable(s));
const gangFor=p=>data.gangs.find(g=>g.id===p.gangId&&g.edition==='N26');
const sideName=p=>p.name||gangFor(p)?.name||'—';
function canWrite(){const a=window.AccountParity;return !(a&&(a.connecting||a.busy||a.account&&!a.ready));}
function message(en,ko){const host=document.querySelector('[data-sk-error]');if(host){host.innerHTML=L(en,ko);host.hidden=false;window.UKI18n?.refresh(host);host.focus?.();}return false;}
function guard(s){return canWrite()&&s&&list().includes(s);}
function die(n=6){const a=new Uint32Array(1);const ceiling=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a);}while(a[0]>=ceiling);return a[0]%n+1;}
function rollTable(key){const found=rows(key);if(![1,2,3,4,5,6].every(n=>found.filter(r=>n>=r.d6_min&&n<=r.d6_max).length===1))return null;const value=die();return {value,row:found.find(r=>value>=r.d6_min&&value<=r.d6_max)};}
function openHome(){if(document.querySelector('.modal-bg'))return false;delete data.selectedSkirmish;data.view='dashboard';data.homeTab='skirmishes';save();return true;}
function openSession(s){if(!usable(s))return false;data.selectedSkirmish=s.id;data.view='dashboard';data.homeTab='skirmishes';save();return true;}
function textInput(key,en,ko,value='',extra=''){return `<label>${L(en,ko)}<input name="${key}" value="${E(value)}" ${extra}></label>`;}
function rosterSelect(i,current){return `<label>${L('Roster '+(i?'B':'A'),'로스터 '+(i?'B':'A'))}<select name="gang${i}"><option value="" data-i18n-en="Enter opponent / paper roster" data-i18n-ko="이름 입력·종이 로스터">Enter opponent / paper roster</option>${data.gangs.filter(g=>g.edition==='N26').map(g=>`<option value="${E(g.id)}" ${current===g.id?'selected':''} data-user-text>${E(g.name)}</option>`).join('')}</select></label>`;}
function create(prefill=''){
 if(!canWrite()||document.querySelector('.modal-bg'))return false;const owner=account();
 formModal(L('Skirmish','스커미시'),`<p class="wide">${L('Prepare a standalone N26 battle. Use a saved roster or enter the name of a paper roster.','독립적인 N26 전투를 준비합니다. 저장한 로스터를 연결하거나 종이 로스터의 이름을 입력하세요.')}</p>${textInput('title','Battle name','전투 이름','','maxlength="100"')}${[0,1].map(i=>rosterSelect(i,i===0?prefill:'')+textInput('name'+i,'Player / gang '+(i?'B':'A'),'플레이어·갱 '+(i?'B':'A'),'','maxlength="100"')).join('')}<p class="wide muted">${L('Use two different sides. Linked rosters are read here; match scores and crew choices are saved separately.','서로 다른 두 편을 정하세요. 연결한 로스터는 읽어서 사용하고 전투 점수와 크루 선택은 별도로 저장합니다.')}</p><p class="wide sk-error" data-sk-error role="alert" hidden></p>`,v=>{
  if(owner!==account()||!canWrite())return message('Account access changed. Reopen the form.','계정 접근 상태가 바뀌었습니다. 창을 다시 열어 주세요.');
  if(v.gang0&&v.gang0===v.gang1)return message('Choose two different rosters.','서로 다른 로스터를 고르세요.');
  const participants=[0,1].map(i=>({name:String(v['name'+i]||'').trim(),gangId:v['gang'+i]||'',role:'',crew:[],vp:0,notes:''}));
  for(const p of participants)if(!p.name&&gangFor(p))p.name=gangFor(p).name;
  if(participants.some(p=>!p.name&&!gangFor(p)))return message('Give each side a roster or a name.','양쪽에 로스터를 연결하거나 이름을 입력하세요.');
  if(participants.some(p=>p.gangId&&!gangFor(p)))return message('A selected roster is no longer available.','선택한 로스터를 더 이상 사용할 수 없습니다.');
  const s={id:id(),name:String(v.title||'').trim()||participants.map(sideName).join(' vs '),edition:'N26',createdAt:now(),stage:'setup',round:1,participants,deploymentId:'',objectiveId:'',crewId:'',checklist:{},notes:''};
  data.skirmishes??=[];data.skirmishes.push(s);data.selectedSkirmish=s.id;data.homeTab='skirmishes';data.view='dashboard';save();return true;
 },'Create Battle');const submit=document.querySelector('#modal-submit');if(submit)submit.innerHTML=L('Create battle','전투 만들기');window.UKI18n?.refresh(document.querySelector('.modal-bg'));return true;
}
function home(){const s=selected();if(s)return detail(s);return `<section class="sk-page"><header class="sk-heading"><div><p class="sk-eyebrow">N26 · ${L('STANDALONE BATTLE','독립 전투')}</p><h1>${L('Skirmish','스커미시')}</h1><p>${L('Choose a mission, set up the battlefield and bring your crew to the table.','미션을 정하고 전장을 준비한 뒤 크루를 이끌고 바로 플레이하세요.')}</p></div>${button('new','New battle','새 전투','','primary')}</header><div class="sk-intro card"><strong>${L('A battle without creating a campaign','캠페인을 만들지 않고 전투 준비')}</strong><p>${L('Deployment, objective and crew tables use the verified N26 rules. Open diagrams and examples whenever you need them.','검증된 N26 배치·목표·크루 표를 사용합니다. 필요한 순간마다 도식과 예시를 열어 볼 수 있습니다.')}</p><p class="muted">${L('A new gang normally has a 1,000-credit founding budget; unspent skirmish credits are lost. This helper does not spend or erase a linked roster’s credits.','새 갱의 창설 예산은 보통 1,000크레딧이며 스커미시에서 미사용분은 소멸합니다. 이 도우미가 연결한 로스터의 크레딧을 차감하거나 지우지는 않습니다.')}</p><div class="actions">${help('sequence','Preparation rules','준비 절차')}${help('budget','Founding budget','창설 예산')}${help('injury','Lasting injuries','지속 부상')}</div></div><div class="sk-match-list">${list().filter(s=>s.edition==='N26').slice().reverse().map(s=>`<article class="card sk-match"><div><small>${L(s.stage==='completed'?'Completed':s.stage==='battle'?'In battle':'Preparing',s.stage==='completed'?'종료':s.stage==='battle'?'플레이 중':'준비 중')}</small><h2 data-user-text>${E(s.name)}</h2><p>${(s.participants||[]).map(p=>literal(sideName(p))).join(' · ')}</p><p>${name(row(s,'objectiveId'))}</p></div><div class="actions">${usable(s)?button('open','Open','열기',`data-sk-id="${E(s.id)}"`):L('Incomplete record · kept in backup','미완성 기록 · 백업에 보존됨')}${button('delete','Delete','삭제',`data-sk-id="${E(s.id)}"`,'small danger')}</div></article>`).join('')||`<div class="card">${L('No skirmishes yet. You can start with paper rosters, too.','아직 스커미시가 없습니다. 종이 로스터만 있어도 시작할 수 있습니다.')}</div>`}</div></section>`;}
function mission(s,key){const r=row(s,key),playing=s.stage!=='setup';return `<section class="card sk-mission"><div class="section-heading"><h2>${L(...labels[key])}</h2>${!playing?button('roll','Roll D6','D6 굴리기',`data-sk-key="${key}"`,'small'):''}</div>${!playing?`<label class="sk-select"><span class="sr-only">${L(...labels[key])}</span><select data-sk-field="${key}"><option value="">—</option>${rows(key).map(r=>`<option value="${E(r.id)}" ${s[key]===r.id?'selected':''} data-i18n-en="${E(r.d6_min+'. '+r.name)}" data-i18n-ko="${E(r.d6_min+'. '+(r.name_ko||r.name))}">${E(r.d6_min+'. '+r.name)}</option>`).join('')}</select></label>`:`<h3>${name(r)}</h3>`}${r?`<p class="sk-rule-summary">${description(r)}</p>${button('scenario-help','Diagram & examples','도식·예시 보기',`data-sk-rule="${E(r.id)}"`,'small')}`:`<p class="muted">${L('Choose from the list or roll the table.','목록에서 고르거나 표를 굴리세요.')}</p>`}${key==='deploymentId'&&r&&r.name!=='Ambush'?`<div class="sk-edge">${!playing?button('edge','Deployment-zone roll-off','배치 구역 롤오프','','small'):''}${rollSummary(s.edgeRoll,s)}</div>`:''}${s.tableRolls?.[key]?`<small class="sk-roll-result">D6: ${E(s.tableRolls[key])}</small>`:''}</section>`;}
function rollSummary(value,s){if(!value)return '';return `<p class="sk-roll-result" aria-live="polite">A ${E(value.dice[0])} · B ${E(value.dice[1])} — ${value.winner<0?L('Tie: roll again','동률: 다시 굴리세요'):literal(sideName(s.participants[value.winner]))+' '+L('wins the roll','롤오프 승리')}</p>`;}
function rolePanel(s){return `<section class="card sk-roles"><div class="section-heading"><h2>${L('1. Attacker & defender','1. 공격자·방어자')}</h2>${help('sequence')}</div><p>${L('Roll a D6 each. The winner chooses who is the attacker. Deployment-edge roll-offs are separate.','각자 D6을 굴려 승자가 공격자가 될 편을 선택합니다. 배치 구역을 고르는 롤오프는 별개입니다.')}</p>${s.stage==='setup'?`<div class="actions">${button('roles','Roll off','롤오프 굴리기')}<label>${L('Attacker chosen by the winner','승자가 정한 공격자')}<select data-sk-field="attacker"><option value="">—</option>${s.participants.map((p,i)=>`<option value="${i}" ${p.role==='attacker'?'selected':''} data-user-text>${E(sideName(p))}</option>`).join('')}</select></label></div>`:`<p>${L('Attacker','공격자')}: ${literal(sideName(s.participants.find(p=>p.role==='attacker')||{}))} · ${L('Defender','방어자')}: ${literal(sideName(s.participants.find(p=>p.role==='defender')||{}))}</p>`}${rollSummary(s.roleRoll,s)}</section>`;}
function planFor(s,p){const r=row(s,'crewId');return r?.rule_data?.both||r?.rule_data?.[p.role]||null;}
function modelPool(g){return (g?.fighters||[]).filter(f=>!f.beastEquipmentStashed&&!f.beast_equipment_stashed);}
function ratingFor(p){const g=gangFor(p);return g?rating(g):null;}
function crewMarkup(s,p,i){const g=gangFor(p),plan=planFor(s,p);return `<section class="card sk-side"><div class="section-heading"><div><small>${p.role?L(p.role==='attacker'?'Attacker':'Defender',p.role==='attacker'?'공격자':'방어자'):L('Role not chosen','역할 미선택')}</small><h2 data-user-text>${E(sideName(p))}</h2></div>${s.stage==='setup'&&g?`<div class="actions">${button('crew','Choose crew','크루 구성',`data-sk-side="${i}"`,'small')}${p.crew.some(c=>c.kind==='reinforcement')?button('reserve','Edit reserves','증원 구성',`data-sk-side="${i}"`,'small'):''}</div>`:''}</div>${g?`<p class="muted">${L('Gang Rating','갱 레이팅')} ${fmt(ratingFor(p))} · ${L('Starting crew','시작 크루')} ${p.crew.filter(c=>c.kind==='starting').length} · ${L('Reinforcements','증원 덱')} ${p.crew.filter(c=>c.kind==='reinforcement').length}</p><ul class="sk-crew-summary">${p.crew.map(c=>{const f=g.fighters.find(f=>f.id===c.fighterId);return `<li>${literal(f?.name||'—')} <small>${c.kind==='reinforcement'?L('Reinforcement','증원'):L('Starting','시작')}${c.loadoutId?' · '+literal(f?.loadouts?.find(l=>l.id===c.loadoutId)?.name||'—'):''}</small></li>`;}).join('')||`<li class="muted">${L('Choose eligible models after selecting the crew table.','크루 표를 정한 뒤 참가 가능한 모델을 고르세요.')}</li>`}</ul>`:`<p class="muted">${L('Paper / external roster. Confirm the crew using the rule above and keep its list below.','종이·외부 로스터입니다. 위의 크루 규칙에 맞춰 명단을 정하고 아래에 적어 두세요.')}</p>`}${plan?.reinforcements?`<p class="sk-reminder">${L('Separate deck','별도 증원 덱')}: ${plan.reinforcements} · ${L('D3 arrivals each End phase from round 1','1라운드부터 매 종료 단계 D3명')} ${help('reinforce')}</p>`:''}<label>${L('Crew / table notes','크루·전장 메모')}<textarea rows="2" maxlength="4000" data-sk-notes="${i}" ${s.stage==='completed'?'readonly':''} data-user-text>${E(noteDrafts.get(noteKey(s,i))??p.notes)}</textarea></label>${s.stage!=='completed'?button('save-notes','Save notes','메모 저장',`data-sk-side="${i}"`,'small'):''}</section>`;}
function tactics(s){const a=ratingFor(s.participants[0]),b=ratingFor(s.participants[1]);return `<section class="sk-tactics"><strong>${L('Gang Tactics','갱 택틱')}</strong><p class="sk-tactics-allowance-label">${L('Selection allowance for this battle','이번 전투 선택 한도')}</p><p class="sk-tactics-allowance">${a==null||b==null?L('Paper / external roster: compare both full Gang Ratings.','종이·외부 로스터: 양쪽 전체 갱 레이팅을 비교하세요.'):s.participants.map((p,i)=>literal(sideName(p))+': '+(1+Math.max(0,Math.floor(((i?a:b)-(i?b:a))/200)))+' '+L('tactic(s)','개')).join(' · ')}</p>${window.MMSkirmishPrepGuide?.tactics()||''}${help('tactics','Selection rules','선택 룰')}</section>`;}

function preparation(s){return `${rolePanel(s)}<div class="sk-section-label"><h2>${L('2. Mission','2. 미션 구성')}</h2><p>${L('Each table is separate. Read its conditions before placing terrain.','세 표는 각각 별개의 결과입니다. 조건을 읽고 지형을 놓으세요.')}</p></div><div class="sk-missions">${Object.keys(keys).map(key=>mission(s,key)).join('')}</div>
<section class="card"><div class="section-heading"><h2>${L('3. Battlefield','3. 전장 설치')}</h2>${help('field','Battlefield setup','전장 준비 룰')}</div><p>${L('Typical board: 3×3–4×4 ft. Starting with the defender, alternate placing terrain, then obstacles.','일반 전장: 3×3~4×4피트. 방어자부터 지형을 번갈아 놓고 장애물을 배치합니다.')}</p><label class="sk-single-check"><input type="checkbox" data-sk-check="terrain" ${s.checklist?.terrain?'checked':''}>${L('Battlefield and obstacles ready','전장·장애물 설치 완료')}</label></section>
<div class="sk-section-label"><h2>${L('4. Crews','4. 크루 구성')}</h2>${help('crew','Selection methods','선택 방식')}</div><div class="sk-sides">${s.participants.map((p,i)=>crewMarkup(s,p,i)).join('')}</div>
<section class="card"><div class="section-heading"><h2>${L('5. Effects, tactics & deployment','5. 전장 효과·택틱·배치')}</h2>${help('deploy','Deployment order','배치 순서')}</div>${window.MMSkirmishPrepGuide?.effects()||''}<div class="sk-checks">${[['effects','Announce battlefield effects','전장 효과 공지'],['tactics','Choose available Gang Tactics for this battle','이번 전투에 쓸 보유 갱 택틱 직접 선택'],['deployment','Defender deploys first, one model at a time','방어자부터 모델 1개씩 교대 배치']].map(([k,en,ko])=>`<label><input type="checkbox" data-sk-check="${k}" ${s.checklist?.[k]?'checked':''}>${L(en,ko)}</label>`).join('')}</div>${tactics(s)}</section>
<div class="sk-start"><p>${L('Match controls record this skirmish only. XP, injuries, credits and campaign rewards are not applied to linked rosters automatically.','전투 조작은 이 스커미시에만 기록합니다. XP·부상·크레딧·캠페인 보상은 연결한 로스터에 자동 적용하지 않습니다.')}</p>${button('start','Start battle','전투 시작','','primary')}</div>`;}

function livePlay(s){return `<section class="card sk-round"><div class="section-heading"><div><small>${L(s.stage==='completed'?'Completed match':'Current round',s.stage==='completed'?'종료된 전투':'현재 라운드')}</small><h2>${L('Round','라운드')} ${s.round}</h2></div>${s.stage==='battle'?button('next-round','Next round','다음 라운드') :''}</div><div class="actions">${s.stage==='battle'?button('priority','Roll Priority','우선권 굴리기'):''}${help('round','Round sequence','라운드 절차')}${help('reinforce','Reinforcements','증원 절차')}</div>${rollSummary(s.priorityRoll,s)}<p class="muted">${L('Priority → Action → End: Bottle checks, victory check, reinforcements. VP is recorded manually after checking the objective.','우선권 → 행동 → 종료: 보틀 체크, 승리 확인, 증원. 목표 조건을 확인한 뒤 VP를 직접 기록하세요.')}</p><div class="sk-scoreboard">${s.participants.map((p,i)=>`<div><strong data-user-text>${E(sideName(p))}</strong><div class="sk-counter">${s.stage==='battle'?button('vp-minus','−','−',`data-sk-side="${i}" aria-label="${E('VP −1 '+sideName(p))}"`):''}<output>${p.vp}</output>${s.stage==='battle'?button('vp-plus','+','+',`data-sk-side="${i}" aria-label="${E('VP +1 '+sideName(p))}"`):''}</div><small>VP</small></div>`).join('')}</div></section><div class="sk-missions">${Object.keys(keys).map(key=>mission(s,key)).join('')}</div><details class="card sk-fold"><summary>${L('Roles, crews & preparation notes','역할·크루·준비 메모')}</summary>${rolePanel(s)}<div class="sk-sides">${s.participants.map((p,i)=>crewMarkup(s,p,i)).join('')}</div>${tactics(s)}</details><section class="sk-unit-section"><div class="section-heading"><h2>${L('Crew quick reference','크루 빠른 확인')}</h2><p>${L('Open a unit to read stats, weapons, skills and rules.','유닛을 펼쳐 스탯·무장·스킬·룰을 확인하세요.')}</p></div>${s.participants.map((p,i)=>{const g=gangFor(p);return g?`<h3 data-user-text>${E(sideName(p))}</h3>${p.crew.map(c=>{const f=g.fighters.find(f=>f.id===c.fighterId);if(!f)return '';const view={...f,loadouts:(f.loadouts||[]).map(l=>({...l,active:l.id===c.loadoutId})),equipment:f.equipment};return `<details class="card sk-unit"><summary>${literal(f.name)} <small>${c.kind==='reinforcement'?L('Reinforcement','증원'):L('Starting crew','시작 크루')}</small></summary>${window.MMPlayMode?.card(view,g)||''}</details>`;}).join('')}`:'';}).join('')}</section>${s.stage==='battle'?`<div class="sk-start">${button('finish','Finish battle','전투 종료','','primary')}</div>`:''}`;}
function detail(s){return `<section class="sk-page" data-sk-session="${E(s.id)}"><div class="sk-top">${button('list','All skirmishes','스커미시 목록','','small')}<span class="sk-eyebrow">N26 · ${L('SKIRMISH','스커미시')}</span></div><header class="sk-heading"><div><h1 data-user-text>${E(s.name)}</h1><p>${s.participants.map(p=>literal(sideName(p))).join(' vs ')}</p></div><span class="chip">${L(s.stage==='setup'?'Preparation':s.stage==='battle'?'In battle':'Completed',s.stage==='setup'?'준비 중':s.stage==='battle'?'플레이 중':'종료')}</span></header><p class="sk-error" data-sk-error role="alert" tabindex="-1" hidden></p>${s.lastNotice?`<p class="sk-reminder" aria-live="polite">${L(s.lastNotice.en,s.lastNotice.ko)}</p>`:''}${s.stage==='setup'?preparation(s):livePlay(s)}</section>`;}
function crewEditor(s,index){const p=s.participants[index],g=gangFor(p),spec=planFor(s,p);if(!guard(s)||s.stage!=='setup'||!g)return false;if(!spec)return message('Choose attacker/defender and the crew table first.','공격자·방어자와 크루 표를 먼저 선택하세요.');
 const token={s,p,g,account:account()},pool=modelPool(g),existing=new Set(p.crew.map(c=>c.fighterId)),plan={chosen:typeof spec.chosen==='number'?spec.chosen:null,random:typeof spec.random==='number'?spec.random:spec.random?null:0,reinforcements:spec.reinforcements||0};
 const line=(k,en,ko)=>`<span>${L(en,ko)} <strong data-sk-plan="${k}">${plan[k]??'D3'}</strong>${plan[k]===null?button('crew-d3','Roll D3','D3 굴리기',`data-sk-plan-key="${k}"`,'small'):''}</span>`;
 formModal(L('Select Crew','크루 구성'),`<div class="wide sk-crew-plan">${line('chosen','Choose','직접 선택')} + ${line('random','Random','무작위')} · ${L('Reinforcement deck','증원 덱')} ${plan.reinforcements}</div><details class="wide sk-crew-instructions"><summary>${L('Eligibility & selection help','참가 조건·선택 방법')}</summary><p>${L('Check eligible models, then choose the required starting models. Random additions have no duplicate models. The helper also generates a random reserve deck for convenience; use Edit reserves after saving to choose its members yourself. Random selections also randomise the equipment set.','참가 가능한 모델을 체크한 뒤 직접 선택 인원을 고르세요. 남은 모델에서 중복 없이 무작위 인원을 뽑습니다. 편의를 위해 증원 덱도 무작위로 구성하며, 저장 후 ‘증원 구성’에서 직접 바꿀 수 있습니다. 무작위 선발은 장비 세트도 무작위로 정합니다.')}</p><p class="muted">${L('Active models are pre-marked as eligible. Check model-specific restrictions and exceptions with your opponent. Shortages are shown after the draw.','활동 중인 모델을 기본 참가 가능으로 표시합니다. 모델별 제한·예외는 상대와 확인하세요. 인원이 부족하면 결과에 표시합니다.')}</p></details><div class="wide sk-crew-picker">${pool.map(f=>`<div class="sk-crew-pick"><label><input type="checkbox" name="eligible" value="${E(f.id)}" ${f.status==='Active'?'checked':''}>${literal(f.name)}<small>${E(f.status)}</small></label><label><input type="checkbox" name="chosen" value="${E(f.id)}" ${existing.has(f.id)&&p.crew.find(c=>c.fighterId===f.id)?.kind==='starting'?'checked':''}>${L('Choose','선택')}</label><label class="sk-loadout">${L('Equipment set','장비 세트')}<select name="loadout-${E(f.id)}">${!f.loadouts?.length?`<option value="" data-i18n-en="All carried equipment" data-i18n-ko="보유 장비">All carried equipment</option>`:''}${(f.loadouts||[]).map(l=>`<option value="${E(l.id)}" data-user-text>${E(l.name)}</option>`).join('')}</select></label></div>`).join('')}</div><p class="wide sk-error" data-sk-error role="alert" hidden></p>`,()=>{
  if(!guard(s)||token.account!==account()||s.stage!=='setup'||gangFor(p)!==g||spec!==planFor(s,p))return message('The account or roster changed. Reopen crew selection.','계정 또는 로스터가 바뀌었습니다. 크루 선택을 다시 열어 주세요.');
  const form=document.querySelector('#modal-form'),eligible=[...form.querySelectorAll('[name=eligible]:checked')].map(n=>pool.find(f=>f.id===n.value)).filter(Boolean),chosen=[...form.querySelectorAll('[name=chosen]:checked')].map(n=>pool.find(f=>f.id===n.value)).filter(Boolean);
  if(plan.chosen===null||plan.random===null)return message('Roll the required D3 first.','필요한 D3을 먼저 굴리세요.');
  if(!eligible.length||chosen.some(f=>!eligible.includes(f))||chosen.length!==Math.min(plan.chosen,eligible.length))return message('Choose the required number from eligible models.','참가 가능한 모델에서 직접 선택 인원만큼 고르세요.');
  if(chosen.some(f=>f.loadouts?.length&&!f.loadouts.some(l=>l.id===form.elements['loadout-'+f.id]?.value)))return message('Choose an equipment set belonging to each model.','각 모델이 보유한 장비 세트를 선택하세요.');
  const remaining=eligible.filter(f=>!chosen.includes(f));for(let i=remaining.length-1;i>0;i--){const j=die(i+1)-1;[remaining[i],remaining[j]]=[remaining[j],remaining[i]];}
  const draw=(f,kind,random)=>{let loadoutId=form.elements['loadout-'+f.id]?.value||'';if(random&&f.loadouts?.length)loadoutId=f.loadouts[die(f.loadouts.length)-1].id;return {fighterId:f.id,loadoutId,kind};};
  const random=remaining.splice(0,plan.random),reinforce=remaining.splice(0,plan.reinforcements);p.crew=[...chosen.map(f=>draw(f,'starting',false)),...random.map(f=>draw(f,'starting',true)),...reinforce.map(f=>draw(f,'reinforcement',true))];p.crewPlan=copy(plan);
  const short=Math.max(0,plan.chosen+plan.random+plan.reinforcements-p.crew.length);s.lastNotice=short?{en:'Crew saved. '+short+' requested model(s) were unavailable; agree any exceptions with your opponent.',ko:'크루를 저장했습니다. 요청 인원 중 '+short+'명이 부족합니다. 예외 적용은 상대와 확인하세요.'}:null;draftCrew=null;save();return true;
 },'Save Crew');draftCrew={...token,plan};document.querySelector('#modal-submit').innerHTML=L('Save crew','크루 저장');window.UKI18n?.refresh(document.querySelector('.modal-bg'));return true;
}
function reserveEditor(s,index){const p=s.participants[index],g=gangFor(p),spec=planFor(s,p);if(!guard(s)||s.stage!=='setup'||!g||!spec?.reinforcements)return false;const owner=account(),starting=new Set(p.crew.filter(c=>c.kind==='starting').map(c=>c.fighterId)),pool=modelPool(g).filter(f=>!starting.has(f.id)),saved=new Set(p.crew.filter(c=>c.kind==='reinforcement').map(c=>c.fighterId));formModal(L('Reinforcement deck','증원 덱'),`<p class="wide">${L('Choose eligible models outside the starting crew. Requested deck size: ','시작 크루에 포함되지 않은 참가 가능한 모델을 고르세요. 규정 덱 인원: ')}${spec.reinforcements}</p><div class="wide sk-crew-picker">${pool.map(f=>`<label><input type="checkbox" name="reserve" value="${E(f.id)}" ${saved.has(f.id)?'checked':''}>${literal(f.name)} <small>${E(f.status)}</small></label>`).join('')}</div><p class="wide sk-error" data-sk-error role="alert" hidden></p>`,()=>{if(owner!==account()||!guard(s)||s.stage!=='setup')return false;const chosen=[...document.querySelectorAll('#modal-form [name=reserve]:checked')].map(n=>pool.find(f=>f.id===n.value)).filter(Boolean);if(chosen.length>spec.reinforcements)return message('Too many models for this reinforcement deck.','증원 덱의 규정 인원보다 많이 선택했습니다.');p.crew=p.crew.filter(c=>c.kind==='starting').concat(chosen.map(f=>({fighterId:f.id,loadoutId:f.loadouts?.length?f.loadouts[die(f.loadouts.length)-1].id:'',kind:'reinforcement'})));save();return true;},'Save');window.UKI18n?.refresh(document.querySelector('.modal-bg'));return true;}
const previousTabs=homeTabs;homeTabs=function(active){return previousTabs(active).replace('<button data-parity="home" data-value="campaigns"',button('home','Skirmish','스커미시','',active==='skirmishes'?'active':'')+'<button data-parity="home" data-value="campaigns"');};
const previousDashboard=dashboard;dashboard=function(){return data.homeTab==='skirmishes'?homeTabs('skirmishes')+home():previousDashboard.apply(this,arguments);};
const previousTop=gangTop;gangTop=function(g){const html=previousTop.apply(this,arguments);return g.edition==='N26'?html.replace('<div class="entity-actions main-actions">','<div class="entity-actions main-actions">'+button('new','Skirmish','스커미시',`data-sk-gang="${E(g.id)}"`)):html;};
function refresh(){if(data.view!=='dashboard'||data.homeTab!=='skirmishes')return;const crumb=document.querySelector('.crumb');if(crumb)crumb.innerHTML=`<span>${window.MMIcon?.('home',18)||'⌂'}</span> / ${L('Skirmish','스커미시')}`;const host=document.querySelector('.sk-page');if(host)window.UKI18n?.refresh(host);}
const previousRender=render;render=function(...args){const result=previousRender.apply(this,args);refresh();return result;};
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-sk-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.skAction,s=selected();
 if(action==='help')return window.MMRuleReference?.open('coreRules',b.dataset.skRule,{edition:'n26',activator:b});if(action==='scenario-help')return window.MMRuleReference?.open('scenarioEntries',b.dataset.skRule,{edition:'n26',activator:b});
 if(action==='home')return openHome();if(action==='new')return create(b.dataset.skGang||'');if(action==='open')return openSession(list().find(x=>x.id===b.dataset.skId));
 if(action==='crew-d3'){if(draftCrew&&draftCrew.account===account()){const k=b.dataset.skPlanKey;if(['chosen','random'].includes(k)){draftCrew.plan[k]=die(3);document.querySelector('[data-sk-plan="'+k+'"]').textContent=draftCrew.plan[k];b.remove();}}return;}
 if(action==='save-notes'&&guard(s)&&s.stage!=='completed'){const i=Number(b.dataset.skSide),p=s.participants[i];if(p){p.notes=String(noteDrafts.get(noteKey(s,i))??p.notes).slice(0,4000);noteDrafts.delete(noteKey(s,i));save();}return;}if(action==='list'){delete data.selectedSkirmish;save();return;}if(action==='delete'){const target=list().find(x=>x.id===b.dataset.skId),owner=account();if(!guard(target))return;return showModal(L('Delete Skirmish','스커미시 삭제'),`<p>${literal(target.name)}</p><p>${L('Delete this match record?','이 전투 기록을 삭제할까요?')}</p>`,'Delete',()=>{if(owner!==account()||!guard(target))return false;data.skirmishes=data.skirmishes.filter(x=>x!==target);save();return true;});}
 if(!guard(s)||!document.querySelector('.sk-page'))return;
 if(action==='roll'&&s.stage==='setup'){const result=rollTable(b.dataset.skKey);if(!result)return;setMission(s,b.dataset.skKey,result.row.id);s.tableRolls??={};s.tableRolls[b.dataset.skKey]=result.value;save();}
 else if(action==='roles'&&s.stage==='setup'){const dice=[die(),die()];s.roleRoll={dice,winner:dice[0]===dice[1]?-1:dice[0]>dice[1]?0:1};save();}
 else if(action==='edge'&&s.stage==='setup'){const dice=[die(),die()];s.edgeRoll={dice,winner:dice[0]===dice[1]?-1:dice[0]>dice[1]?0:1};save();}
 else if(action==='reserve')reserveEditor(s,Number(b.dataset.skSide));
 else if(action==='crew')crewEditor(s,Number(b.dataset.skSide));
 else if(action==='start'&&s.stage==='setup'){if(!Object.keys(keys).every(k=>row(s,k))||!s.participants.every(p=>p.role)||s.participants.some(p=>gangFor(p)&&!p.crew.length))return message('Choose roles, all three mission parts, and linked crews first.','역할·미션 세 항목·연결한 로스터의 크루를 먼저 정하세요.');s.stage='battle';s.lastNotice=null;save();window.scrollTo?.({top:0});}
 else if(action==='priority'&&s.stage==='battle'){const dice=[die(),die()],previous=s.previousPriority;let winner=dice[0]===dice[1]?(s.round>1&&Number.isInteger(previous)?1-previous:-1):dice[0]>dice[1]?0:1;s.priorityRoll={dice,winner};save();}
 else if(action==='next-round'&&s.stage==='battle'){if(s.round>=999)return;if(!(s.priorityRoll?.winner>=0))return message('Resolve Priority before moving to the next round.','우선권을 결정한 뒤 다음 라운드로 넘어가세요.');if(s.priorityRoll?.winner>=0)s.previousPriority=s.priorityRoll.winner;else delete s.previousPriority;s.round++;delete s.priorityRoll;save();}
 else if(['vp-plus','vp-minus'].includes(action)&&s.stage==='battle'){const p=s.participants[Number(b.dataset.skSide)];if(p){p.vp=Math.max(0,Math.min(999,p.vp+(action==='vp-plus'?1:-1)));save();}}
 else if(action==='finish'&&s.stage==='battle'){const owner=account();showModal(L('Finish Skirmish','스커미시 종료'),`<p>${L('Finish this match and keep the scores? No rewards or injuries will be applied to a roster.','현재 점수를 남기고 전투를 종료할까요? 로스터에 보상이나 부상을 적용하지 않습니다.')}</p>`,'Finish',()=>{if(owner!==account()||!guard(s)||s.stage!=='battle')return false;s.stage='completed';save();return true;});document.querySelector('#modal-submit').innerHTML=L('Finish','종료');window.UKI18n?.refresh(document.querySelector('.modal-bg'));}
},true);
function setMission(s,key,value){if(!Object.hasOwn(keys,key)||!rows(key).some(r=>r.id===value)&&value!=='')return false;s[key]=value;if(key==='deploymentId')delete s.edgeRoll;if(s.tableRolls)delete s.tableRolls[key];if(key==='crewId')for(const p of s.participants){p.crew=[];delete p.crewPlan;}return true;}
document.addEventListener('change',e=>{const n=e.target,s=selected();if(!guard(s)||!n.closest('.sk-page'))return;if(n.dataset.skField&&s.stage==='setup'){const k=n.dataset.skField;if(k==='attacker'){if(!['0','1',''].includes(n.value))return;s.participants.forEach((p,i)=>{p.role=n.value===''?'':i===Number(n.value)?'attacker':'defender';p.crew=[];delete p.crewPlan;});}else setMission(s,k,n.value);save();}else if(n.dataset.skCheck&&s.stage==='setup'){s.checklist??={};s.checklist[n.dataset.skCheck]=n.checked;save();}});
document.addEventListener('input',e=>{const n=e.target,s=selected();if(s&&n.dataset.skNotes!=null&&n.closest('.sk-page')&&guard(s)&&s.stage!=='completed')noteDrafts.set(noteKey(s,Number(n.dataset.skNotes)),n.value.slice(0,4000));});
window.MMSkirmish={openHome,create,open:openSession,rows,rollTable,die,planFor,crewEditor};
})();
